def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]
    opp_moves = [o for _, o in history]
    my_moves = [m for m, _ in history]
    opp_def = sum(1 for o in opp_moves if o == 'D')
    my_def = sum(1 for m in my_moves if m == 'D')

    # Always defect against very defective opponents
    if n >= 5 and opp_def > 0.6 * n:
        return 'D'

    # If opponent never defected, cooperate with occasional random test
    if opp_def == 0:
        if n >= 20 and rng.random() < 0.03:
            return 'D'
        return 'C'

    # Count consecutive opponent defections
    consec_opp_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            consec_opp_d += 1
        else:
            break

    # If opponent has defected 3 or more times in a row, forgive to break cycle
    if consec_opp_d >= 3:
        return 'C'

    # If opponent defected last round
    if opp_last == 'D':
        # If they defected twice in a row, punish
        if consec_opp_d >= 2:
            return 'D'
        # Single defection: forgive if overall defection rate is low, else punish
        if opp_def < 0.2 * n:
            return 'C'
        else:
            return 'D'

    # Opponent cooperated
    if opp_last == 'C':
        # If we defected last round, continue defecting to exploit (they didn't retaliate)
        if my_last == 'D':
            return 'D'
        # Otherwise cooperate, but occasionally test
        if n >= 20 and rng.random() < 0.05:
            return 'D'
        return 'C'

    return 'C'
